# -*- coding: utf-8 -*-
exec(open('lib4.py',encoding='utf-8').read())
c='p6';B='CSDL 5'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 5','AN TOÀN VÀ PHÂN QUYỀN<br>CƠ SỞ DỮ LIỆU','Mối đe doạ, xác thực – phân quyền, GRANT/REVOKE, SQL injection, sao lưu – phục hồi, mã hoá.',['phân quyền','GRANT','SQL injection','sao lưu','mã hoá']))
S.append(goals(c,B,['Nêu các <b>mối đe doạ</b> đối với CSDL.','Phân biệt <b>xác thực</b> và <b>phân quyền</b>.','Dùng <b>GRANT, REVOKE</b> cấp và thu hồi quyền.','Giải thích <b>SQL injection</b> và cách phòng chống.','Nêu biện pháp <b>sao lưu, phục hồi, mã hoá</b>.'],['Mối đe doạ','Xác thực và phân quyền','SQL injection','Sao lưu, mã hoá','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Vì sao cần bảo vệ CSDL?',card('Dữ liệu là tài sản',ul(['CSDL chứa <b>thông tin cá nhân, tài chính, nghiệp vụ</b>.','Lộ, mất, sửa trái phép gây <b>thiệt hại lớn</b>.','Luật bảo vệ dữ liệu cá nhân quy định <b>trách nhiệm</b> của đơn vị quản lí.'],6)),KEY('Ba mục tiêu an toàn thông tin (<b>CIA</b>): <b>bí mật</b> (Confidentiality), <b>toàn vẹn</b> (Integrity), <b>sẵn sàng</b> (Availability).')))
S.append(TB(c,B+' · 1','Các mối đe doạ với CSDL',['Mối đe doạ','Ví dụ','Hậu quả'],[['Truy cập trái phép','đoán mật khẩu, dùng tài khoản của người khác','lộ dữ liệu'],['<b>SQL injection</b>','nhập mã SQL vào ô đăng nhập','đọc, sửa, xoá dữ liệu'],['Mã độc, tấn công mạng','ransomware mã hoá dữ liệu đòi tiền','mất dữ liệu, ngừng dịch vụ'],['Lỗi người dùng','xoá nhầm, quên WHERE','mất, sai dữ liệu'],['Sự cố phần cứng, thiên tai','hỏng đĩa, cháy','mất dữ liệu'],['Mối đe doạ từ bên trong','nhân viên lạm quyền','lộ, sửa trái phép']],note=KEY('Biện pháp: <b>kiểm soát truy cập</b>, <b>mã hoá</b>, <b>sao lưu</b>, <b>cập nhật phần mềm</b>, <b>giám sát</b>, <b>đào tạo</b> người dùng.')))
S.append(S2(c,B+' · 2','Xác thực và phân quyền',T(tr('','Xác thực','Phân quyền',h=True)+tr('Câu hỏi','Bạn <b>là ai</b>?','Bạn được <b>làm gì</b>?')+tr('Cách làm','tên đăng nhập + mật khẩu, mã OTP, vân tay','gán <b>quyền</b> theo người dùng/vai trò')+tr('Thứ tự','<b>trước</b>','<b>sau</b> xác thực')),KEY('Quy trình: <b>đăng nhập (xác thực)</b> → hệ thống tra <b>quyền</b> → cho phép hoặc từ chối thao tác.')+OK('<b>Xác thực hai yếu tố</b> (2FA): mật khẩu + mã OTP, an toàn hơn chỉ dùng mật khẩu.')))
S.append(TB(c,B+' · 2','Các quyền trên CSDL',['Quyền','Cho phép','Lệnh SQL'],[['SELECT','xem dữ liệu','<code>SELECT</code>'],['INSERT','thêm bản ghi','<code>INSERT</code>'],['UPDATE','sửa bản ghi','<code>UPDATE</code>'],['DELETE','xoá bản ghi','<code>DELETE</code>'],['CREATE / ALTER / DROP','tạo, sửa, xoá bảng','DDL'],['ALL PRIVILEGES','mọi quyền','—']],mono=1,note=WARN('Nguyên tắc <b>đặc quyền tối thiểu</b>: chỉ cấp quyền <b>đủ để làm việc</b>, không hơn.')))
S.append(S2(c,B+' · 2','GRANT và REVOKE',CODE('-- cấp quyền xem và thêm cho giáo viên\nGRANT SELECT, INSERT\n  ON truong.hocsinh\n  TO giaovien;\n\n-- thu hồi quyền thêm\nREVOKE INSERT\n  ON truong.hocsinh\n  FROM giaovien;',21),card('Ý nghĩa',ul(['<b>GRANT</b> quyền <b>ON</b> đối tượng <b>TO</b> người dùng.','<b>REVOKE</b> quyền <b>ON</b> đối tượng <b>FROM</b> người dùng.','Thuộc nhóm <b>DCL</b>.'],6))+KEY('SQLite không có GRANT/REVOKE; MySQL, SQL Server, PostgreSQL có.')))
S.append(S2(c,B+' · 2','Ví dụ phân quyền theo vai trò',T(tr('Vai trò','SELECT','INSERT/UPDATE','DELETE','DDL',h=True)+tr('Quản trị','có','có','có','<b>có</b>')+tr('Giáo viên','có','điểm của lớp mình','—','—')+tr('Học sinh','điểm của mình','—','—','—')+tr('Khách','—','—','—','—')),KEY('<b>Vai trò (role)</b>: nhóm quyền gán cho nhiều người; đổi vai trò là đổi quyền một lần.')+OK('Quyền theo <b>hàng/cột</b>: học sinh chỉ xem được điểm <b>của mình</b> (dùng VIEW hoặc điều kiện lọc).')))
S.append(S2(c,B+' · 3','SQL injection là gì?',card('Khái niệm',ul(['Kẻ tấn công <b>chèn mã SQL</b> vào dữ liệu nhập (ô đăng nhập, tìm kiếm).','Nguyên nhân: ứng dụng <b>ghép chuỗi</b> dữ liệu người dùng vào câu SQL.','Hậu quả: <b>đăng nhập không cần mật khẩu</b>, đọc/sửa/xoá dữ liệu.'],6)),KEY('Câu SQL ghép: <code>"SELECT * FROM user WHERE ten=\'" + ten + "\' AND mk=\'" + mk + "\'"</code>')+WARN('Nhập tên: <code>admin\' --</code> thì phần kiểm tra mật khẩu bị <b>biến thành chú thích</b>.')))
S.append(PYR(c,B+' · 3','Mô phỏng tấn công SQL injection','import sqlite3\ncon = sqlite3.connect(":memory:")\ncon.execute("CREATE TABLE u(ten TEXT, mk TEXT)")\ncon.execute("INSERT INTO u VALUES (\'admin\', \'S3cr3t\')")\n\ndef dang_nhap(ten, mk):\n    q = "SELECT * FROM u WHERE ten=\'" + ten + "\' AND mk=\'" + mk + "\'"\n    return con.execute(q).fetchall()\n\nprint(dang_nhap("admin", "sai"))\nprint(dang_nhap("admin\' --", "bất kì"))',KEY('Lần 2: câu SQL thành <code>… ten=\'admin\' --\' AND mk=…</code>: phần sau <b>--</b> là chú thích nên <b>bỏ qua mật khẩu</b> và đăng nhập được!'),18))
S.append(PYR(c,B+' · 3','Phòng chống: câu lệnh tham số hoá','import sqlite3\ncon = sqlite3.connect(":memory:")\ncon.execute("CREATE TABLE u(ten TEXT, mk TEXT)")\ncon.execute("INSERT INTO u VALUES (\'admin\', \'S3cr3t\')")\n\ndef dang_nhap(ten, mk):\n    q = "SELECT * FROM u WHERE ten=? AND mk=?"\n    return con.execute(q, (ten, mk)).fetchall()\n\nprint(dang_nhap("admin", "S3cr3t"))\nprint(dang_nhap("admin\' --", "bất kì"))',KEY('Dấu <b>?</b> là <b>tham số</b>: dữ liệu luôn được coi là <b>giá trị</b>, không bao giờ là mã SQL → mã chèn vào <b>vô hiệu</b>.'),18))
S.append(TB(c,B+' · 3','Cách phòng chống SQL injection',['Biện pháp','Giải thích'],[['<b>Truy vấn tham số hoá</b>','không ghép chuỗi; dùng <code>?</code> hoặc tham số có tên'],['Kiểm tra, lọc dữ liệu nhập','giới hạn kiểu, độ dài, kí tự'],['Đặc quyền tối thiểu','tài khoản của ứng dụng <b>chỉ có SELECT/INSERT</b> cần thiết'],['Không hiện lỗi chi tiết ra ngoài','tránh lộ tên bảng, cột'],['Cập nhật phần mềm','vá lỗ hổng đã biết']],note=KEY('Quy tắc vàng: <b>không bao giờ tin dữ liệu người dùng nhập</b>.')))
S.append(S2(c,B+' · 4','Sao lưu và phục hồi',card('Sao lưu (backup)',ul(['<b>Toàn bộ</b>: sao chép mọi dữ liệu.','<b>Gia tăng</b>: chỉ phần thay đổi từ lần trước.','Lưu bản sao ở <b>nơi khác</b> (máy chủ khác, đám mây).','Kiểm tra bản sao <b>khôi phục được</b>.'],6)),KEY('Quy tắc <b>3-2-1</b>: <b>3</b> bản sao, trên <b>2</b> loại thiết bị, <b>1</b> bản để <b>ngoài địa điểm</b>.')+OK('<b>Phục hồi</b> (restore): đưa CSDL về trạng thái của bản sao khi có sự cố; <b>nhật kí giao dịch</b> giúp phục hồi đến thời điểm gần nhất.')))
S.append(S2(c,B+' · 4','Mã hoá dữ liệu',card('Hai nơi cần mã hoá',ul(['<b>Khi lưu trữ</b>: mã hoá đĩa, cột nhạy cảm.','<b>Khi truyền</b>: dùng <b>HTTPS/TLS</b>.','<b>Mật khẩu</b> không lưu nguyên văn: lưu <b>giá trị băm</b> (hash) kèm “muối”.'],6)),KEY('<b>Băm</b> là một chiều: không giải ngược được; so sánh bằng cách băm mật khẩu nhập vào rồi đối chiếu.')))
S.append(PYR(c,B+' · 4','Băm mật khẩu với hashlib','import hashlib\ndef bam(mk, muoi="x9"):\n    return hashlib.sha256((muoi + mk).encode()).hexdigest()\n\nluu = bam("S3cr3t")\nprint(luu[:20], "...")\nprint(bam("S3cr3t") == luu)\nprint(bam("s3cr3t") == luu)',KEY('Cùng mật khẩu → cùng mã băm; sai <b>một kí tự</b> → mã băm hoàn toàn khác. CSDL bị lộ thì kẻ xấu chỉ thấy <b>mã băm</b>.'),21))
S.append(TB(c,B+' · 4','Mật khẩu mạnh và thói quen an toàn',['Nên','Không nên'],[['Dài (≥ 12 kí tự), có chữ hoa, thường, số, kí hiệu','dùng ngày sinh, 123456, tên mình'],['Mỗi dịch vụ <b>một mật khẩu</b>','dùng chung một mật khẩu ở nhiều nơi'],['Bật <b>xác thực hai yếu tố</b>','chia sẻ mật khẩu qua tin nhắn'],['Dùng trình quản lí mật khẩu','ghi mật khẩu lên giấy dán màn hình'],['Đăng xuất khi dùng máy công cộng','lưu mật khẩu trên máy lạ']],note=KEY('Người dùng là <b>mắt xích yếu nhất</b>: tấn công <b>lừa đảo</b> (phishing) nhắm vào con người.')))
S.append(S2(c,B+' · 4','Pháp luật và đạo đức dữ liệu',card('Trách nhiệm',ul(['Chỉ <b>thu thập đủ</b> dữ liệu cần thiết, có <b>sự đồng ý</b> của người dùng.','<b>Bảo mật</b> thông tin cá nhân; thông báo khi bị lộ.','Truy cập trái phép, phát tán dữ liệu cá nhân là <b>vi phạm pháp luật</b> (Luật An ninh mạng, Luật Bảo vệ dữ liệu cá nhân).'],6)),KEY('Người làm CNTT phải tuân thủ <b>đạo đức nghề nghiệp</b>: không lạm quyền truy cập dữ liệu của người khác.')))
S+=END(c,B,['<b>CIA</b>: bí mật, toàn vẹn, sẵn sàng.','<b>Xác thực</b> (bạn là ai) trước, <b>phân quyền</b> (bạn được làm gì) sau.','<b>GRANT / REVOKE</b>; nguyên tắc <b>đặc quyền tối thiểu</b>.','<b>SQL injection</b> phòng bằng <b>truy vấn tham số hoá</b>.','<b>Sao lưu 3-2-1</b>, <b>mã hoá</b>, mật khẩu lưu dạng <b>băm</b>.'],[('Cấp quyền','GRANT'),('Thu quyền','REVOKE'),('Chống injection','tham số hoá'),('Lưu mật khẩu','băm + muối')],'Ghép chuỗi SQL với dữ liệu nhập là lỗ hổng nghiêm trọng.',['Băm khác <b>mã hoá</b>: băm một chiều; mã hoá hai chiều (có khoá giải mã).','<b>Phishing</b> không phải lỗ hổng CSDL nhưng lấy được tài khoản.','Sao lưu <b>không kiểm tra</b> khôi phục = chưa chắc có bản sao.','2FA cũng có thể bị vượt nếu người dùng bị lừa mã OTP.'],['<b>RBAC</b> (kiểm soát truy cập theo vai trò).','<b>Audit log</b>: ghi lại ai làm gì.','<b>Data masking</b>: che dữ liệu nhạy cảm (số thẻ).'],
 [('Phân biệt xác thực và phân quyền.',),('Viết lệnh cấp cho người dùng <code>hocsinh_xem</code> quyền chỉ xem bảng DIEM.',),('Nêu hai biện pháp phòng chống SQL injection.',),('Vì sao không nên lưu mật khẩu dạng văn bản thường?',),('Quy tắc sao lưu 3-2-1 là gì?',)],
 [('Xác thực: kiểm tra <b>danh tính</b>; phân quyền: xác định <b>được làm gì</b> sau khi biết danh tính.',),('<code>GRANT SELECT ON truong.diem TO hocsinh_xem;</code>',),('Truy vấn <b>tham số hoá</b>; kiểm tra, lọc dữ liệu nhập; đặc quyền tối thiểu.',),('CSDL bị lộ là lộ mật khẩu; phải lưu <b>giá trị băm</b> kèm muối.',),('<b>3</b> bản sao, <b>2</b> loại thiết bị, <b>1</b> bản ngoài địa điểm.',)],
 [('Câu <code>"SELECT * FROM sp WHERE ten LIKE \'%" + t + "%\'"</code> có lỗ hổng không? Nhập gì để lấy toàn bộ bảng?',),('Một ứng dụng dùng tài khoản CSDL có quyền DROP TABLE. Rủi ro gì? Cách khắc phục?',),('Đúng hay sai: (a) Băm có thể giải ngược ra mật khẩu. (b) HTTPS bảo vệ dữ liệu khi truyền. (c) REVOKE thuộc DML. (d) Sao lưu cùng ổ đĩa với dữ liệu là đủ an toàn.',),('Nêu ba nguyên nhân khiến dữ liệu CSDL có thể bị mất và biện pháp tương ứng.',),('Thiết kế phân quyền cho hệ thống tra cứu điểm gồm: quản trị, giáo viên, học sinh.',),('Khi phát hiện CSDL bị tấn công, các bước xử lí ban đầu là gì?',)],
 [('<b>Có</b>. Nhập <code>\' OR \'1\'=\'1</code> làm điều kiện luôn đúng, trả mọi sản phẩm. Phòng bằng tham số hoá.',),('Nếu bị tấn công, kẻ xấu có thể <b>xoá bảng</b>. Khắc phục: cấp tài khoản ứng dụng <b>chỉ SELECT/INSERT/UPDATE</b> cần thiết.',),('(a) <b>Sai</b>. (b) <b>Đúng</b>. (c) <b>Sai</b>: thuộc DCL. (d) <b>Sai</b>: ổ hỏng là mất cả hai.',),('Hỏng phần cứng → sao lưu; tấn công mã độc → cập nhật, phòng thủ, sao lưu ngoài; người dùng xoá nhầm → phân quyền, nhật kí, phục hồi.',),('Quản trị: toàn quyền; giáo viên: xem/sửa điểm lớp mình; học sinh: chỉ xem điểm của mình.',),('Cô lập hệ thống; <b>đổi mật khẩu</b>; xem <b>nhật kí</b>; <b>khôi phục</b> từ bản sao sạch; vá lỗ hổng; thông báo theo quy định.',)],hper=2)
mkdeck('c5.html','CSDL 5 · An toàn và phân quyền cơ sở dữ liệu',S)
